(function(){
'use strict';
let C=null,S=null,root=null,tab='overview',settingsTab='general',orderView='list',selectedOrders=new Set(),bound=false;
const $q=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const n=v=>Number(v||0).toLocaleString('en-US');
const money=v=>n(v)+' تومان';
const checked=v=>v===true||v===1||v==='1'||v==='true';
const faStatus=s=>({pending_payment:'در انتظار پرداخت',receipt_submitted:'رسید ارسال شده',reviewing:'در بررسی',payment_confirmed:'پرداخت تاییدشده',preparing:'آماده‌سازی',delivered:'تحویل‌شده',rejected:'رد شده',canceled:'لغوشده',refunded:'مرجوع‌شده'}[s]||s||'—');
function toast(m,t='info'){C?.toast?.(m,t)}
function setState(x){if(x&&(x.report||x.products||x.orders||x.settings)){S=x;C?.setState?.(x)}else if(x?.admin_roles&&S){S.admin_roles=x.admin_roles;C?.setState?.(S)}renderPane()}
async function call(a,b={},msg='انجام شد.'){root?.classList.add('admin-busy');try{const r=await C.api(a,b);if(r.report||r.products||r.orders||r.settings)setState(r);else{if(r.admin_roles&&S)S.admin_roles=r.admin_roles;if(r.message)msg=r.message;await reload(false)}toast(msg,'success');return r}catch(e){toast(e.message||'خطا','error');throw e}finally{root?.classList.remove('admin-busy')}}
async function reload(show=true){S=await C.api('admin_summary');C?.setState?.(S);if(show)toast('پنل بروزرسانی شد.','success');renderPane()}
function fmtDate(v){if(!v)return '—';try{return new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(String(v).replace(' ','T')))}catch(_){return esc(v)}}
function downloadCsv(name,rows){const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function modal(title,html,opts={}){let m=document.getElementById('bgAdminModal');if(!m){m=document.createElement('div');m.id='bgAdminModal';m.className='bg-admin-modal hidden';document.body.appendChild(m)}m.innerHTML=`<div class="bg-admin-modal-backdrop" data-admin-modal-close></div><section class="bg-admin-modal-card ${opts.wide?'wide':''}" role="dialog" aria-modal="true"><header><div><small>${esc(opts.kicker||'BLUEGATE ADMIN')}</small><h3>${title}</h3></div><button type="button" class="bg-admin-icon" data-admin-modal-close>✕</button></header><div class="bg-admin-modal-body">${html}</div></section>`;m.classList.remove('hidden');document.documentElement.classList.add('bg-admin-lock');return m}
function closeModal(){document.getElementById('bgAdminModal')?.classList.add('hidden');document.documentElement.classList.remove('bg-admin-lock')}
function formDataObj(f){const fd=new FormData(f),o={};for(const [k,v] of fd.entries())o[k]=v;return o}
function productOptions(sel=''){return `<option value="">انتخاب محصول</option>${(S.products||[]).map(p=>`<option value="${p.id}" ${String(sel)===String(p.id)?'selected':''}>#${p.id} ${esc(p.name)}</option>`).join('')}`}
function categoryOptions(sel=''){return `<option value="">بدون دسته</option>${(S.categories||[]).map(c=>`<option value="${c.id}" ${String(sel)===String(c.id)?'selected':''}>${esc(c.emoji||'🛒')} ${esc(c.title)}</option>`).join('')}`}
function variantOptions(sel='',pid=''){return `<option value="">بدون پلن</option>${(S.variants||[]).filter(v=>!pid||String(v.product_id)===String(pid)).map(v=>`<option value="${v.id}" ${String(sel)===String(v.id)?'selected':''}>#${v.id} ${esc(v.product_name||'')} — ${esc(v.title)}</option>`).join('')}`}
function topNav(){const tabs=[['overview','📊','داشبورد'],['orders','🧾','سفارش‌ها'],['products','🛒','محصولات'],['categories','🗂','دسته‌ها'],['variants','📐','پلن‌ها'],['inventory','📦','انبار'],['coupons','🎟','تخفیف'],['withdrawals','🏧','برداشت‌ها'],['customers','👥','کاربران'],['activity','📜','لاگ'],['roles','🛡','نقش‌ها'],['settings','⚙️','تنظیمات'],['backups','💾','بکاپ']];return `<aside class="bg-admin-nav"><div class="bg-admin-nav-head"><span>BG</span><div><b>BlueGate Admin</b><small>پنل مدیریت کامل</small></div></div><nav>${tabs.map(x=>`<button data-bgadmin-tab="${x[0]}" class="${tab===x[0]?'active':''}"><span>${x[1]}</span>${x[2]}</button>`).join('')}</nav><div class="bg-admin-nav-foot"><button data-bgadmin-action="broadcast">📢 پیام همگانی</button><button data-bgadmin-action="reward">🎁 پاداش خرید</button></div></aside>`}
function header(){const r=S.report||{};return `<header class="bg-admin-header"><div><span class="eyebrow">BLUEGATE CONTROL CENTER</span><h2>مدیریت BlueGate</h2><p>تمام قابلیت‌های مدیریتی Mini App در نسخه وب، با فضای بزرگ‌تر و خوانایی بیشتر.</p></div><div class="bg-admin-header-actions"><div class="bg-admin-live"><i></i><span>${n(r.pending||0)} نیازمند اقدام</span></div><button data-bgadmin-action="reload">↻ بروزرسانی</button></div></header>`}
function shell(){root.innerHTML=`<div class="bg-admin-shell">${topNav()}<main class="bg-admin-main">${header()}<div class="bg-admin-mobile-tabs">${[['overview','📊'],['orders','🧾'],['products','🛒'],['settings','⚙️'],['backups','💾']].map(x=>`<button data-bgadmin-tab="${x[0]}" class="${tab===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><div id="bgAdminPane"></div></main></div>`;bind();renderPane()}
function pane(){return document.getElementById('bgAdminPane')}
function stat(label,value,sub,icon){return `<article class="bg-admin-stat"><span>${icon}</span><small>${label}</small><strong>${value}</strong><p>${sub}</p></article>`}
function renderOverview(){const r=S.report||{},orders=S.orders||[],prods=S.products||[],inv=S.inventory||[],low=prods.filter(p=>checked(p.is_active)&&Number(p.inventory_available||0)<3);const top=r.top||[];const pm={};orders.forEach(o=>{const k=o.payment_method_fa||o.payment_method||'نامشخص';pm[k]=(pm[k]||0)+1});return `<section class="bg-admin-stats">${stat('فروش امروز',money(r.today?.s||0),`${n(r.today?.c||0)} سفارش`,'☀️')}${stat('فروش ماه',money(r.month?.s||0),`${n(r.month?.c||0)} سفارش`,'📈')}${stat('نیازمند اقدام',n(r.pending||0),'سفارش باز','🛎')}${stat('محصولات فعال',n(prods.filter(p=>checked(p.is_active)).length),`${n(prods.length)} محصول کل`,'🛒')}</section><section class="bg-admin-grid two"><article class="bg-admin-card"><div class="bg-card-head"><div><h3>⚡ دسترسی سریع</h3><p>بخش‌های پرتکرار مدیریت</p></div></div><div class="bg-quick-grid"><button data-bgadmin-tab="orders">🧾<b>سفارش‌ها</b></button><button data-bgadmin-tab="products">🛒<b>محصولات</b></button><button data-bgadmin-tab="inventory">📦<b>انبار</b></button><button data-bgadmin-tab="settings">⚙️<b>تنظیمات</b></button><button data-bgadmin-action="broadcast">📢<b>Broadcast</b></button><button data-bgadmin-action="reward">🎁<b>پاداش خرید</b></button></div></article><article class="bg-admin-card"><div class="bg-card-head"><div><h3>🔮 پیش‌بینی فروش</h3><p>بر اساس ۳۰ روز اخیر</p></div></div>${S.forecast?.forecast?`<div class="forecast-big">${money(S.forecast.forecast)}</div><div class="bg-admin-muted">میانگین روزانه ${money(S.forecast.daily_avg||0)} • تغییر ${n(Math.abs(S.forecast.change_percent||0))}٪</div>`:'<div class="bg-empty">داده کافی وجود ندارد.</div>'}</article></section>${low.length?`<section class="bg-admin-card warn"><div class="bg-card-head"><div><h3>⚠️ موجودی کم</h3><p>${n(low.length)} محصول کمتر از ۳ آیتم موجودی دارد.</p></div><button data-bgadmin-tab="inventory">رفتن به انبار</button></div><div class="bg-list">${low.slice(0,8).map(p=>`<div><b>${esc(p.name)}</b><span>${n(p.inventory_available||0)} موجود</span></div>`).join('')}</div></section>`:''}<section class="bg-admin-grid two"><article class="bg-admin-card"><div class="bg-card-head"><div><h3>🏆 پرفروش‌ترین‌ها</h3><p>بر اساس گزارش فروش</p></div></div><div class="bg-list">${top.length?top.map((x,i)=>`<div><b>${i+1}. ${esc(x.name)}</b><span>${money(x.s)} • ${n(x.c)} سفارش</span></div>`).join(''):'<div class="bg-empty">داده‌ای نیست.</div>'}</div></article><article class="bg-admin-card"><div class="bg-card-head"><div><h3>💳 روش‌های پرداخت</h3><p>${n(orders.length)} سفارش اخیر</p></div></div><div class="bg-list">${Object.entries(pm).length?Object.entries(pm).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div><b>${esc(k)}</b><span>${n(v)} سفارش</span></div>`).join(''):'<div class="bg-empty">داده‌ای نیست.</div>'}</div></article></section>`}
function orderCard(o){return `<article class="bg-order-card"><div class="bg-order-main"><label class="bg-check"><input type="checkbox" data-order-select="${o.id}" ${selectedOrders.has(Number(o.id))?'checked':''}><span></span></label><div class="bg-order-icon">${o.image_url?`<img src="${esc(o.image_url)}">`:'🧾'}</div><div class="bg-order-copy"><div><strong>#${o.id} • ${esc(o.display_name)}</strong><span class="bg-badge ${esc(o.status||'')}">${esc(o.status_fa||faStatus(o.status))}</span></div><p>${money(o.final_amount)} • ${esc(o.payment_method_fa||o.payment_method||'روش پرداخت مشخص نشده')} • ${fmtDate(o.created_at)}</p>${o.username?`<small>@${esc(o.username)} • Telegram ${esc(o.telegram_id||'')}</small>`:''}</div></div><div class="bg-order-actions"><button data-bgadmin-action="customer" data-user="${o.user_id}">👤 مشتری</button>${o.receipt_file_id?`<button data-bgadmin-action="receipt" data-id="${o.id}">🖼 رسید</button>`:''}<button data-bgadmin-action="order-note" data-id="${o.id}" data-note="${esc(o.admin_note||'')}">📝 یادداشت</button><button data-bgadmin-action="service" data-id="${o.id}" data-url="${esc(o.delivery_url||'')}" data-title="${esc(o.delivery_title||'مدیریت سرویس')}">🌐 لینک سرویس</button><button data-bgadmin-action="deliver" data-id="${o.id}">📦 تحویل متنی</button><select data-order-status="${o.id}"><option value="">تغییر وضعیت…</option>${['reviewing','payment_confirmed','preparing','rejected','canceled','refunded'].map(s=>`<option value="${s}">${faStatus(s)}</option>`).join('')}</select><button data-bgadmin-action="archive-order" data-id="${o.id}">🗄 آرشیو</button>${['rejected','canceled','refunded'].includes(o.status)?`<button class="danger" data-bgadmin-action="delete-order" data-id="${o.id}">🗑 حذف کامل</button>`:''}</div></article>`}
function renderOrders(){const orders=S.orders||[],c=S.cleanup||{};if(orderView==='board'){const cols=[['جدید',['pending_payment','receipt_submitted','reviewing']],['در پردازش',['payment_confirmed','preparing']],['تحویل',['delivered']],['رد/لغو',['rejected','canceled','refunded']]];return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🧾 مدیریت سفارش‌ها</h3><p>${n(orders.length)} سفارش اخیر</p></div>${orderToolbar()}</div></section><div class="bg-kanban">${cols.map(([title,sts])=>`<section><header><b>${title}</b><span>${n(orders.filter(o=>sts.includes(o.status)).length)}</span></header>${orders.filter(o=>sts.includes(o.status)).map(o=>`<button class="bg-kanban-card" data-bgadmin-action="order-open" data-id="${o.id}"><b>#${o.id} ${esc(o.display_name)}</b><span>${money(o.final_amount)}</span><small>${esc(o.status_fa||faStatus(o.status))}</small></button>`).join('')||'<div class="bg-empty">خالی</div>'}</section>`).join('')}</div>`}return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🧾 مدیریت سفارش‌ها</h3><p>جستجو، عملیات گروهی، مشاهده رسید و مدیریت کامل چرخه سفارش</p></div>${orderToolbar()}</div><form class="bg-admin-form bg-order-search" data-admin-form="order-search"><label>جستجو<input name="search" placeholder="#123، محصول، یوزرنیم یا Telegram ID"></label><label>وضعیت<select name="status"><option value="all">همه</option>${['pending_payment','receipt_submitted','reviewing','payment_confirmed','preparing','delivered','rejected','canceled','refunded'].map(s=>`<option value="${s}">${faStatus(s)}</option>`).join('')}</select></label><button>جستجو</button></form></section>${selectedOrders.size?`<section class="bg-admin-card accent"><div class="bg-card-head"><div><h3>☑️ ${n(selectedOrders.size)} سفارش انتخاب شده</h3><p>عملیات گروهی روی انتخاب‌ها</p></div><div class="bg-inline"><button data-bgadmin-action="bulk-status" data-status="payment_confirmed">تایید پرداخت</button><button data-bgadmin-action="bulk-status" data-status="preparing">آماده‌سازی</button><button class="danger" data-bgadmin-action="bulk-status" data-status="rejected">رد</button><button data-bgadmin-action="clear-selection">پاک کردن انتخاب</button></div></div></section>`:''}<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🧹 پاکسازی</h3><p>فقط سفارش‌های لغو/رد/مرجوع‌شده حذف کامل می‌شوند.</p></div><div class="bg-inline"><button class="danger" data-bgadmin-action="cleanup" data-days="">همه (${n(c.all||0)})</button><button data-bgadmin-action="cleanup" data-days="7">قدیمی‌تر از ۷ روز (${n(c.older_7||0)})</button><button data-bgadmin-action="cleanup" data-days="30">قدیمی‌تر از ۳۰ روز (${n(c.older_30||0)})</button></div></div></section><div id="bgOrderResults" class="bg-order-list">${orders.map(orderCard).join('')||'<div class="bg-empty">سفارشی نیست.</div>'}</div>`}
function orderToolbar(){return `<div class="bg-inline"><button data-bgadmin-action="order-view" data-view="${orderView==='list'?'board':'list'}">${orderView==='list'?'▦ کانبان':'☷ لیست'}</button><button data-bgadmin-action="export-orders">📥 CSV</button></div>`}
function productRow(p,i){const arr=S.products||[];return `<article class="bg-admin-row"><div class="bg-admin-thumb">${p.image_url?`<img src="${esc(p.image_url)}">`:'🛒'}</div><div class="bg-admin-row-main"><div><strong>${esc(p.name)}</strong><span>#${p.id}</span>${checked(p.is_featured)?'<span class="bg-badge featured">ویژه</span>':''}${checked(p.is_active)?'<span class="bg-badge delivered">فعال</span>':'<span class="bg-badge rejected">غیرفعال</span>'}</div><p>${esc(p.category_title||'بدون دسته')} • ${esc(p.price_label||money(p.price))} • موجودی ${n(p.inventory_available||0)}</p></div><div class="bg-row-actions"><button data-bgadmin-action="reorder-product" data-id="${p.id}" data-dir="up" ${i===0?'disabled':''}>▲</button><button data-bgadmin-action="reorder-product" data-id="${p.id}" data-dir="down" ${i===arr.length-1?'disabled':''}>▼</button><button data-bgadmin-action="edit-product" data-id="${p.id}">ویرایش</button><button data-bgadmin-action="toggle-product" data-id="${p.id}">${checked(p.is_active)?'غیرفعال':'فعال'}</button><button data-bgadmin-action="add-variant" data-id="${p.id}">+ پلن</button><button class="danger" data-bgadmin-action="soft-delete-product" data-id="${p.id}">حذف امن</button><button class="danger" data-bgadmin-action="hard-delete-product" data-id="${p.id}">حذف کامل</button></div></article>`}
function renderProducts(){return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🛒 محصولات</h3><p>ساخت، ویرایش، ترتیب، وضعیت و قیمت‌گذاری</p></div><div class="bg-inline"><button data-bgadmin-action="add-product">+ محصول جدید</button><button data-bgadmin-action="export-products">📥 CSV</button></div></div></section><div class="bg-admin-list">${(S.products||[]).map(productRow).join('')||'<div class="bg-empty">محصولی نیست.</div>'}</div>`}
function renderCategories(){return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🗂 دسته‌بندی‌ها</h3><p>دسته‌بندی Storefront و Mini App</p></div><button data-bgadmin-action="add-category">+ دسته جدید</button></div></section><div class="bg-admin-list">${(S.categories||[]).map((c,i,arr)=>`<article class="bg-admin-row"><div class="bg-admin-thumb emoji">${esc(c.emoji||'🛒')}</div><div class="bg-admin-row-main"><div><strong>${esc(c.title)}</strong><span>#${c.id}</span>${checked(c.is_active)?'<span class="bg-badge delivered">فعال</span>':'<span class="bg-badge rejected">غیرفعال</span>'}</div><p>ترتیب ${n(c.sort_order||0)} ${c.image_url?'• دارای تصویر':''}</p></div><div class="bg-row-actions"><button data-bgadmin-action="reorder-category" data-id="${c.id}" data-dir="up" ${i===0?'disabled':''}>▲</button><button data-bgadmin-action="reorder-category" data-id="${c.id}" data-dir="down" ${i===arr.length-1?'disabled':''}>▼</button><button data-bgadmin-action="edit-category" data-id="${c.id}">ویرایش</button><button class="danger" data-bgadmin-action="soft-delete-category" data-id="${c.id}">حذف امن</button><button class="danger" data-bgadmin-action="hard-delete-category" data-id="${c.id}">حذف کامل</button></div></article>`).join('')||'<div class="bg-empty">دسته‌ای نیست.</div>'}</div>`}
function renderVariants(){const by={};(S.variants||[]).forEach(v=>(by[v.product_id]||(by[v.product_id]=[])).push(v));return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>📐 پلن‌ها / Variantها</h3><p>قیمت، مدت، تخفیف و وضعیت هر پلن</p></div><button data-bgadmin-action="add-variant">+ پلن جدید</button></div></section><div class="bg-admin-list">${(S.products||[]).map(p=>`<details class="bg-admin-details"><summary><div><b>${esc(p.name)}</b><span>${n((by[p.id]||[]).length)} پلن</span></div><i>⌄</i></summary><div>${(by[p.id]||[]).map(v=>`<article class="bg-admin-row compact"><div class="bg-admin-thumb emoji">📐</div><div class="bg-admin-row-main"><div><strong>${esc(v.title)}</strong><span>#${v.id}</span>${checked(v.is_active)?'<span class="bg-badge delivered">فعال</span>':'<span class="bg-badge rejected">غیرفعال</span>'}</div><p>${esc(v.price_label||money(v.price))} • ${n(v.duration_days||0)} روز • تخفیف ${n(v.discount_percent||0)}٪</p></div><div class="bg-row-actions"><button data-bgadmin-action="edit-variant" data-id="${v.id}">ویرایش</button><button class="danger" data-bgadmin-action="soft-delete-variant" data-id="${v.id}">حذف امن</button><button class="danger" data-bgadmin-action="hard-delete-variant" data-id="${v.id}">حذف کامل</button></div></article>`).join('')||'<div class="bg-empty">پلنی ندارد.</div>'}<button class="bg-add-inside" data-bgadmin-action="add-variant" data-id="${p.id}">+ افزودن پلن برای ${esc(p.name)}</button></div></details>`).join('')}</div>`}
function renderInventory(){return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>📦 انبار</h3><p>اکانت، کد، لینک و تحویل خودکار</p></div><button data-bgadmin-action="add-inventory">+ موجودی جدید</button></div><div class="bg-filter-summary"><span>کل ${n((S.inventory||[]).length)}</span><span>آزاد ${n((S.inventory||[]).filter(x=>x.status==='available').length)}</span><span>فروخته ${n((S.inventory||[]).filter(x=>x.status==='sold').length)}</span></div></section><div class="bg-admin-list">${(S.inventory||[]).map(i=>`<article class="bg-admin-row"><div class="bg-admin-thumb emoji">📦</div><div class="bg-admin-row-main"><div><strong>#${i.id} ${esc(i.product_name||'محصول')}</strong><span class="bg-badge ${i.status==='available'?'delivered':i.status==='sold'?'featured':'reviewing'}">${esc(i.status)}</span></div><p>${i.variant_title?esc(i.variant_title)+' • ':''}${esc(String(i.content||'').slice(0,110))}</p></div><div class="bg-row-actions"><button data-bgadmin-action="edit-inventory" data-id="${i.id}">ویرایش کامل</button><button class="danger" data-bgadmin-action="soft-delete-inventory" data-id="${i.id}">حذف امن</button><button class="danger" data-bgadmin-action="hard-delete-inventory" data-id="${i.id}">حذف کامل</button></div></article>`).join('')||'<div class="bg-empty">انبار خالی است.</div>'}</div>`}
function renderCoupons(){return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🎟 کدهای تخفیف</h3><p>محدودیت، انقضا و وضعیت استفاده</p></div><button data-bgadmin-action="add-coupon">+ کد جدید</button></div></section><div class="bg-admin-list">${(S.coupons||[]).map(c=>`<article class="bg-admin-row"><div class="bg-admin-thumb emoji">🎟</div><div class="bg-admin-row-main"><div><strong>${esc(c.code)}</strong>${checked(c.is_active)?'<span class="bg-badge delivered">فعال</span>':'<span class="bg-badge rejected">غیرفعال</span>'}</div><p>${esc(c.discount_type||c.type)} • ${n(c.discount_value||c.value)} • استفاده ${n(c.used_count||0)}/${Number(c.max_uses||0)?n(c.max_uses):'∞'} ${c.expires_at?'• انقضا '+esc(c.expires_at):''}</p></div><div class="bg-row-actions"><button data-bgadmin-action="edit-coupon" data-id="${c.id}">ویرایش</button><button data-bgadmin-action="toggle-coupon" data-id="${c.id}">${checked(c.is_active)?'غیرفعال':'فعال'}</button><button class="danger" data-bgadmin-action="delete-coupon" data-id="${c.id}">حذف</button></div></article>`).join('')||'<div class="bg-empty">کدی نیست.</div>'}</div>`}
function renderWithdrawals(){const w=S.withdrawals||[];const sum=st=>w.filter(x=>x.status===st).reduce((a,x)=>a+Number(x.amount||0),0);return `<section class="bg-admin-stats three">${stat('در انتظار',money(sum('pending')),`${n(w.filter(x=>x.status==='pending').length)} درخواست`,'⏳')}${stat('پرداخت‌شده',money(sum('paid')),`${n(w.filter(x=>x.status==='paid').length)} درخواست`,'✅')}${stat('ردشده',money(sum('rejected')),`${n(w.filter(x=>x.status==='rejected').length)} درخواست`,'❌')}</section><div class="bg-admin-list">${w.map(x=>`<article class="bg-admin-row"><div class="bg-admin-thumb emoji">🏧</div><div class="bg-admin-row-main"><div><strong>#${x.id} ${esc(x.first_name||x.username||x.telegram_id)}</strong><span class="bg-badge ${x.status==='paid'?'delivered':x.status==='rejected'?'rejected':'reviewing'}">${esc(x.status)}</span></div><p>${money(x.amount)} • ${esc(x.card_info||'')} • ${fmtDate(x.created_at)}</p></div><div class="bg-row-actions"><button data-bgadmin-action="withdraw" data-id="${x.id}" data-status="paid">تایید</button><button class="danger" data-bgadmin-action="withdraw" data-id="${x.id}" data-status="rejected">رد</button></div></article>`).join('')||'<div class="bg-empty">درخواستی نیست.</div>'}</div>`}
function renderCustomers(){return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>👥 Customer 360</h3><p>مشاهده کامل کاربر، موجودی و سفارش‌ها</p></div></div><form class="bg-admin-form inline" data-admin-form="customer-lookup"><label>User ID داخلی<input name="user_id" type="number" min="1" required placeholder="مثلاً 42"></label><button>باز کردن پروفایل</button></form></section><section class="bg-admin-card"><div class="bg-card-head"><div><h3>💰 تغییر موجودی سریع</h3><p>با Telegram ID مبلغ مثبت یا منفی ثبت کن.</p></div></div><form class="bg-admin-form inline" data-admin-form="balance"><label>Telegram ID<input name="telegram_id" type="number" required></label><label>مبلغ<input name="amount" type="number" required placeholder="50000 یا -50000"></label><button>اعمال</button></form></section>`}
function renderActivity(){const log=S.activity_log||[];return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>📜 لاگ فعالیت ادمین‌ها</h3><p>${n(log.length)} اقدام اخیر</p></div></div><div class="bg-activity">${log.map(l=>`<article><span>📌</span><div><b>${esc(l.action)}</b>${l.entity_type?` <code>${esc(l.entity_type)}${l.entity_id?' #'+l.entity_id:''}</code>`:''}<p>${esc(l.details||'بدون توضیح')}</p><small>ادمین ${esc(l.admin_telegram_id)} • ${esc(l.created_at||'')}</small></div></article>`).join('')||'<div class="bg-empty">لاگی نیست.</div>'}</div></section>`}
function renderRoles(){const roles=S.admin_roles||[];return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>🛡 نقش ادمین‌ها</h3><p>Full / Orders / Products / Finance</p></div><button data-bgadmin-action="add-role">+ ادمین جدید</button></div></section><div class="bg-admin-list">${roles.map(r=>`<article class="bg-admin-row"><div class="bg-admin-thumb emoji">${r.role==='full'?'👑':r.role==='orders'?'🧾':r.role==='products'?'🛒':'🏧'}</div><div class="bg-admin-row-main"><div><strong>${esc(r.display_name||'بدون نام')}</strong><span class="bg-badge featured">${esc(r.role)}</span></div><p>Telegram ID: ${esc(r.telegram_id)} • ${esc(String(r.created_at||'').slice(0,10))}</p></div><div class="bg-row-actions"><button data-bgadmin-action="edit-role" data-tid="${r.telegram_id}" data-role="${esc(r.role)}" data-name="${esc(r.display_name||'')}">ویرایش</button><button class="danger" data-bgadmin-action="remove-role" data-tid="${r.telegram_id}">حذف نقش</button></div></article>`).join('')||'<div class="bg-empty">نقش جداگانه‌ای تعریف نشده؛ ADMIN_IDS در config دسترسی کامل دارد.</div>'}</div>`}
function settingsTabs(){return `<div class="bg-settings-tabs">${[['general','🏪 عمومی'],['payments','💳 پرداخت'],['crypto','🪙 کریپتو'],['appearance','🎨 ظاهر'],['gamification','🎡 پاداش']].map(x=>`<button data-settings-tab="${x[0]}" class="${settingsTab===x[0]?'active':''}">${x[1]}</button>`).join('')}</div>`}
function settingsFormGeneral(s){return `<div class="bg-admin-grid two"><section class="bg-admin-card"><h3>🏷 هویت فروشگاه</h3><div class="bg-admin-form"><label>نام برند<input name="brand_name" value="${esc(s.brand_name||'BlueGate')}"></label><label>زیرعنوان<input name="storefront_brand_subtitle" value="${esc(s.storefront_brand_subtitle||'')}"></label><label>پشتیبانی<input name="support_username" value="${esc(s.support_username||'')}"></label><label>ارز پایه<select name="default_base_currency"><option ${s.default_base_currency==='USDT'?'selected':''}>USDT</option><option ${s.default_base_currency==='IRR'?'selected':''}>IRR</option><option ${s.default_base_currency==='STARS'?'selected':''}>STARS</option></select></label></div></section><section class="bg-admin-card"><h3>🔐 ورود و ایمیل</h3><div class="bg-admin-form"><label>Resend API Key<input name="resend_api_key" type="password" value="${esc(s.resend_api_key||'')}"></label><label>Sender Email<input name="resend_from_email" value="${esc(s.resend_from_email||'')}"></label><label class="bg-switch"><input name="require_email_verification" type="checkbox" ${checked(s.require_email_verification)?'checked':''}><span>تایید ایمیل اجباری</span></label><label class="bg-switch"><input name="require_contact_auth" type="checkbox" ${checked(s.require_contact_auth)?'checked':''}><span>احراز شماره تماس</span></label><label class="bg-switch"><input name="notify_new_user" type="checkbox" ${checked(s.notify_new_user)?'checked':''}><span>اعلان کاربر جدید</span></label></div></section><section class="bg-admin-card full"><h3>🏪 Storefront</h3><div class="bg-admin-form cols2"><label class="full">Hero Title<input name="storefront_hero_title" value="${esc(s.storefront_hero_title||'')}"></label><label class="full">Hero Text<textarea name="storefront_hero_text">${esc(s.storefront_hero_text||'')}</textarea></label><label class="full">متن اطلاعیه<input name="storefront_announcement_text" value="${esc(s.storefront_announcement_text||'')}"></label><label class="bg-switch"><input name="storefront_announcement_enabled" type="checkbox" ${checked(s.storefront_announcement_enabled)?'checked':''}><span>اطلاعیه فعال</span></label><label>حداقل برداشت<input name="min_withdraw" type="number" value="${esc(s.min_withdraw||0)}"></label><label>پاداش شروع<input name="start_reward" type="number" value="${esc(s.start_reward||0)}"></label></div></section></div>`}
function settingsFormPayments(s){const pm=s.payment_methods_enabled||{};return `<div class="bg-admin-grid two"><section class="bg-admin-card"><h3>💳 روش‌های پرداخت</h3><div class="bg-admin-form"><label class="bg-switch"><input name="pm_wallet" type="checkbox" ${checked(pm.wallet)?'checked':''}><span>کیف پول</span></label><label class="bg-switch"><input name="pm_card" type="checkbox" ${checked(pm.card)?'checked':''}><span>کارت به کارت</span></label><label class="bg-switch"><input name="pm_crypto" type="checkbox" ${checked(pm.crypto)?'checked':''}><span>کریپتو</span></label><label class="bg-switch"><input name="pm_stars" type="checkbox" ${checked(pm.stars)?'checked':''}><span>Telegram Stars</span></label><label>نرخ Stars<input name="stars_rate_toman" type="number" value="${esc(s.stars_rate_toman||0)}"></label><label class="full">دستور پرداخت<textarea name="payment_instructions">${esc(s.payment_instructions||'')}</textarea></label></div></section><section class="bg-admin-card"><h3>⭐ فروش Stars</h3><div class="bg-admin-form cols2"><label>مبنای قیمت<select name="storefront_stars_price_basis"><option value="toman" ${s.storefront_stars_price_basis==='toman'?'selected':''}>تومان</option><option value="usdt" ${s.storefront_stars_price_basis==='usdt'?'selected':''}>USDT</option></select></label><label>هر Star تومان<input name="storefront_star_sell_per_unit_toman" type="number" step="0.0001" value="${esc(s.storefront_star_sell_per_unit_toman||0)}"></label><label>هر Star USDT<input name="storefront_star_sell_per_unit_usdt" type="number" step="0.0001" value="${esc(s.storefront_star_sell_per_unit_usdt||0)}"></label><label>حداقل<input name="storefront_stars_min" type="number" value="${esc(s.storefront_stars_min||50)}"></label><label>حداکثر<input name="storefront_stars_max" type="number" value="${esc(s.storefront_stars_max||10000)}"></label><label>Step<input name="storefront_stars_step" type="number" value="${esc(s.storefront_stars_step||25)}"></label><label class="full">Presetها<input name="storefront_stars_presets" value="${esc((s.storefront_stars_presets||[]).join(','))}"></label></div></section><section class="bg-admin-card full"><h3>🏦 حساب‌های کارت</h3><p class="bg-admin-muted">هر خط: عنوان | شماره کارت | صاحب حساب | شبا</p><textarea class="bg-big-textarea" name="card_accounts_text">${esc(s.card_accounts_text||'')}</textarea></section></div>`}
function settingsFormCrypto(s){const cache=s.crypto_rate_cache||{};return `<div class="bg-admin-grid two"><section class="bg-admin-card"><h3>🪙 تنظیمات نرخ</h3><div class="bg-admin-form cols2"><label>منبع<select name="crypto_rate_source">${['auto','wallex','ramzinex','nobitex','manual'].map(x=>`<option value="${x}" ${s.crypto_rate_source===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Markup %<input name="crypto_rate_markup_percent" type="number" step="0.01" value="${esc(s.crypto_rate_markup_percent||0)}"></label><label>Refresh ثانیه<input name="crypto_rate_refresh_interval_seconds" type="number" min="60" value="${esc(s.crypto_rate_refresh_interval_seconds||600)}"></label><label>اولویت Provider<input name="crypto_rate_provider_priority" value="${esc(s.crypto_rate_provider_priority||'wallex,ramzinex,nobitex')}"></label><label class="bg-switch full"><input name="crypto_notify_rate_fail" type="checkbox" ${checked(s.crypto_notify_rate_fail)?'checked':''}><span>اعلان خطای نرخ</span></label></div><button type="button" data-bgadmin-action="refresh-rates">↻ دریافت نرخ تازه</button></section><section class="bg-admin-card"><h3>📡 Cache نرخ</h3><div class="bg-list">${Object.entries(cache).map(([k,v])=>`<div><b>${esc(k)}</b><span>${typeof v==='object'?esc(JSON.stringify(v)):esc(v)}</span></div>`).join('')||'<div class="bg-empty">خالی</div>'}</div></section><section class="bg-admin-card full"><h3>👛 Wallet Builder</h3><p class="bg-admin-muted">هر خط: عنوان | شبکه | ارز | آدرس | نماد نرخ | فعال | ترتیب</p><textarea class="bg-big-textarea" name="crypto_wallets_text">${esc(s.crypto_wallets_text||'')}</textarea></section><section class="bg-admin-card full"><h3>🧮 نرخ دستی</h3><p class="bg-admin-muted">هر خط مثل USDT|85000</p><textarea class="bg-big-textarea" name="crypto_manual_rates_text">${esc(s.crypto_manual_rates_text||'')}</textarea></section></div>`}
function settingsFormAppearance(s){const bc=s.button_colors||{};return `<div class="bg-admin-grid two"><section class="bg-admin-card"><h3>🎨 تم</h3><div class="bg-admin-form"><label>رنگ اصلی<input name="theme_color" type="color" value="${esc(s.theme_color||'#1d9bf0')}"></label><label class="bg-switch"><input name="button_colors_enabled" type="checkbox" ${checked(s.button_colors_enabled)?'checked':''}><span>رنگ دکمه‌های سفارشی</span></label></div></section><section class="bg-admin-card"><h3>🧩 رنگ دکمه‌ها</h3><div class="bg-admin-form cols2">${['primary','secondary','danger','success','warning'].map(k=>`<label>${k}<input name="button_${k}" type="color" value="${esc(bc[k]||'#1d9bf0')}"></label>`).join('')}</div></section></div>`}
function settingsFormGamification(s){const vip=s.vip_tier_rates||[];return `<div class="bg-admin-grid two"><section class="bg-admin-card"><h3>🎡 گردونه</h3><div class="bg-admin-form"><label>تعداد Referral برای هر شانس<input name="spin_referrals_per_chance" type="number" min="1" value="${esc(s.spin_referrals_per_chance||5)}"></label><label>جوایز گردونه<textarea name="spin_rewards_text">${esc(s.spin_rewards_text||'')}</textarea></label></div></section><section class="bg-admin-card"><h3>💎 نرخ‌های VIP</h3><p class="bg-admin-muted">JSON آرایه نرخ‌ها؛ همان ساختار Mini App.</p><textarea class="bg-big-textarea" name="vip_json">${esc(JSON.stringify(vip,null,2))}</textarea><button type="button" data-bgadmin-action="save-vip">ذخیره نرخ VIP</button></section></div>`}
function renderSettings(){const s=S.settings||{};return `<section class="bg-admin-card"><div class="bg-card-head"><div><h3>⚙️ مرکز تنظیمات</h3><p>همه تنظیمات مشترک Website، Mini App و Bot — تغییر تب‌ها مقادیر واردشده را حفظ می‌کند.</p></div><button data-bgadmin-action="save-settings">ذخیره همه</button></div>${settingsTabs()}</section><form id="bgAdminSettingsForm" class="bg-settings-form"><div class="bg-settings-pane ${settingsTab==='general'?'':'hidden'}" data-settings-pane="general">${settingsFormGeneral(s)}</div><div class="bg-settings-pane ${settingsTab==='payments'?'':'hidden'}" data-settings-pane="payments">${settingsFormPayments(s)}</div><div class="bg-settings-pane ${settingsTab==='crypto'?'':'hidden'}" data-settings-pane="crypto">${settingsFormCrypto(s)}</div><div class="bg-settings-pane ${settingsTab==='appearance'?'':'hidden'}" data-settings-pane="appearance">${settingsFormAppearance(s)}</div><div class="bg-settings-pane ${settingsTab==='gamification'?'':'hidden'}" data-settings-pane="gamification">${settingsFormGamification(s)}</div></form>`}
function renderBackups(){const rows=S.backups||[],st=S.settings||{};return `<section class="bg-admin-grid two"><article class="bg-admin-card"><div class="bg-card-head"><div><h3>💾 ساخت بکاپ</h3><p>آخرین: ${esc(st.backup_last_created_at||'—')}</p></div></div><div class="bg-inline"><button data-bgadmin-action="backup-create">ساخت روی سرور</button><button data-bgadmin-action="backup-send">ساخت و ارسال در Bot</button></div><div class="bg-hint">مسیر VPS: <code>/var/www/bluegate-platform/storage/backups/</code></div></article><article class="bg-admin-card danger-zone"><h3>♻️ Upload & Restore</h3><p>کل دیتابیس جایگزین می‌شود و قبلش Safety Backup گرفته می‌شود.</p><input id="bgBackupUpload" type="file" accept=".json,.gz,.json.gz"><button class="danger" data-bgadmin-action="backup-upload">Upload & Restore</button></article></section><section class="bg-admin-card"><div class="bg-card-head"><div><h3>🗂 بکاپ‌های سرور</h3><p>${n(rows.length)} فایل</p></div></div><div class="bg-admin-list">${rows.map(b=>`<article class="bg-admin-row compact"><div class="bg-admin-thumb emoji">💾</div><div class="bg-admin-row-main"><div><strong>${esc(b.filename||b.name)}</strong></div><p>${esc(b.created_at||'')} • ${n(b.size||0)} bytes</p></div><div class="bg-row-actions">${b.download_url?`<a class="bg-admin-linkbtn" href="${esc(b.download_url)}" target="_blank">دانلود</a>`:''}<button data-bgadmin-action="backup-restore" data-name="${esc(b.filename||b.name)}">Restore</button><button class="danger" data-bgadmin-action="backup-delete" data-name="${esc(b.filename||b.name)}">حذف</button></div></article>`).join('')||'<div class="bg-empty">بکاپی نیست.</div>'}</div></section>`}
function renderPane(){const p=pane();if(!p)return;const map={overview:renderOverview,orders:renderOrders,products:renderProducts,categories:renderCategories,variants:renderVariants,inventory:renderInventory,coupons:renderCoupons,withdrawals:renderWithdrawals,customers:renderCustomers,activity:renderActivity,roles:renderRoles,settings:renderSettings,backups:renderBackups};p.innerHTML=(map[tab]||renderOverview)();$$('[data-bgadmin-tab]',root).forEach(b=>b.classList.toggle('active',b.dataset.bgadminTab===tab));}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function productForm(p={}){return `<form class="bg-admin-form cols2" data-admin-modal-form="${p.id?'edit-product':'add-product'}" data-id="${p.id||''}">${field('نام','name',p.name||'')}
<label>دسته<select name="category_id">${categoryOptions(p.category_id)}</select></label><label>ارز<select name="price_currency"><option value="IRT" ${p.price_currency!=='USD'?'selected':''}>تومان</option><option value="USD" ${p.price_currency==='USD'?'selected':''}>USD</option></select></label>${field('قیمت تومان','price',p.price||0,'number','min="0"')}${field('قیمت USD','price_usd',p.price_usd||'','number','step="0.0001"')}${field('مدت روز','duration_days',p.duration_days||0,'number')}
<label>نوع تحویل<select name="delivery_type">${['manual','account','vpn','code','file'].map(x=>`<option value="${x}" ${p.delivery_type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>نوع پورسانت<select name="commission_type">${['none','percent','fixed'].map(x=>`<option value="${x}" ${p.commission_type===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('مقدار پورسانت','commission_value',p.commission_value||0,'number')}${field('لینک تصویر','image_url',p.image_url||'')}
<label class="full">توضیح کوتاه<textarea name="short_description">${esc(p.short_description||'')}</textarea></label><label class="full">توضیح کامل<textarea name="full_description">${esc(p.full_description||'')}</textarea></label><label class="bg-switch"><input name="is_featured" type="checkbox" ${checked(p.is_featured)?'checked':''}><span>ویژه</span></label>${p.id?`<label class="bg-switch"><input name="is_active" type="checkbox" ${checked(p.is_active)?'checked':''}><span>فعال</span></label>`:''}<button class="full" type="submit">${p.id?'ذخیره محصول':'ساخت محصول'}</button></form>`}
function categoryForm(c={}){return `<form class="bg-admin-form cols2" data-admin-modal-form="${c.id?'edit-category':'add-category'}" data-id="${c.id||''}">${field('نام دسته','title',c.title||'')}${field('ایموجی','emoji',c.emoji||'🛒')}${field('لینک تصویر','image_url',c.image_url||'')}${field('ترتیب','sort_order',c.sort_order||0,'number')}${c.id?`<label class="bg-switch"><input name="is_active" type="checkbox" ${checked(c.is_active)?'checked':''}><span>فعال</span></label>`:''}<button class="full" type="submit">ذخیره</button></form>`}
function variantForm(v={},pid=''){return `<form class="bg-admin-form cols2" data-admin-modal-form="${v.id?'edit-variant':'add-variant'}" data-id="${v.id||''}"><label>محصول<select name="product_id" ${v.id?'disabled':''}>${productOptions(v.product_id||pid)}</select></label>${field('نام پلن','title',v.title||'')}
<label>ارز<select name="price_currency"><option value="IRT" ${v.price_currency!=='USD'?'selected':''}>تومان</option><option value="USD" ${v.price_currency==='USD'?'selected':''}>USD</option></select></label>${field('قیمت تومان','price',v.price||0,'number')}${field('قیمت USD','price_usd',v.price_usd||'','number','step="0.0001"')}${field('مدت روز','duration_days',v.duration_days||0,'number')}${field('تخفیف %','discount_percent',v.discount_percent||0,'number','min="0" max="100" step="0.01"')}${field('ترتیب','sort_order',v.sort_order||99,'number')}<label class="full">توضیح<textarea name="description">${esc(v.description||'')}</textarea></label>${v.id?`<label class="bg-switch"><input name="is_active" type="checkbox" ${checked(v.is_active)?'checked':''}><span>فعال</span></label>`:''}<button class="full" type="submit">ذخیره پلن</button></form>`}
function inventoryForm(i={}){return `<form class="bg-admin-form cols2" data-admin-modal-form="${i.id?'edit-inventory':'add-inventory'}" data-id="${i.id||''}"><label>محصول<select name="product_id">${productOptions(i.product_id)}</select></label><label>پلن<select name="variant_id">${variantOptions(i.variant_id,i.product_id)}</select></label>${i.id?`<label>وضعیت<select name="status">${['available','reserved','sold'].map(x=>`<option ${i.status===x?'selected':''}>${x}</option>`).join('')}</select></label>`:''}<label class="full">محتوا<textarea name="content">${esc(i.content||'')}</textarea></label><button class="full" type="submit">ذخیره انبار</button></form>`}
function couponForm(c={}){return `<form class="bg-admin-form cols2" data-admin-modal-form="${c.id?'edit-coupon':'add-coupon'}" data-id="${c.id||''}">${field('کد','code',c.code||'')}<label>نوع<select name="discount_type"><option value="percent" ${(c.discount_type||c.type)==='percent'?'selected':''}>درصد</option><option value="fixed" ${(c.discount_type||c.type)==='fixed'?'selected':''}>ثابت</option></select></label>${field('مقدار','discount_value',c.discount_value||c.value||0,'number')}${field('حداقل سفارش','min_order_amount',c.min_order_amount||0,'number')}${field('حداکثر استفاده','max_uses',c.max_uses||0,'number')}${field('حداکثر هر کاربر','max_uses_per_user',c.max_uses_per_user||1,'number')}<label>دسته<select name="category_id">${categoryOptions(c.category_id)}</select></label>${field('انقضا','expires_at',c.expires_at||'','datetime-local')}${c.id?`<label class="bg-switch"><input name="is_active" type="checkbox" ${checked(c.is_active)?'checked':''}><span>فعال</span></label>`:''}<button class="full" type="submit">ذخیره کد</button></form>`}
function roleForm(r={}){return `<form class="bg-admin-form" data-admin-modal-form="role">${field('Telegram ID','telegram_id',r.telegram_id||'','number')}${field('نام نمایشی','display_name',r.display_name||'')}<label>نقش<select name="role">${['full','orders','products','finance'].map(x=>`<option value="${x}" ${r.role===x?'selected':''}>${x}</option>`).join('')}</select></label><button type="submit">ذخیره نقش</button></form>`}
async function customerModal(uid){const r=await C.api('admin_customer_view',{user_id:uid}),u=r.user||{};modal('Customer 360',`<div class="bg-customer-hero"><div class="avatar">${esc(String(u.first_name||u.username||'?').slice(0,1).toUpperCase())}</div><div><h3>${esc(u.first_name||u.username||'کاربر')}</h3><p>User #${u.id} • Telegram ${esc(u.telegram_id||'—')} ${u.username?'• @'+esc(u.username):''}</p></div></div><div class="bg-admin-stats three">${stat('موجودی',money(u.balance||0),'کیف پول','💰')}${stat('کل خرید',money(r.total_spent||0),`${n((r.orders||[]).length)} سفارش`,'🧾')}${stat('زیرمجموعه',n(u.referrals_count||0),'Referral','👥')}</div><div class="bg-inline"><button data-bgadmin-action="edit-user" data-id="${u.id}">ویرایش کاربر</button><button class="danger" data-bgadmin-action="ban-user" data-tid="${u.telegram_id||0}">مسدود کردن</button></div><section class="bg-admin-card"><h3>سفارش‌های اخیر</h3><div class="bg-list">${(r.orders||[]).slice(0,10).map(o=>`<div><b>#${o.id} ${esc(o.display_name)}</b><span>${money(o.final_amount)} • ${esc(o.status_fa||o.status)}</span></div>`).join('')||'<div class="bg-empty">سفارشی نیست.</div>'}</div></section>`,{wide:true})}
async function editUserModal(uid){const r=await C.api('admin_get_user',{user_id:uid}),u=r.user||{};modal('ویرایش کاربر',`<form class="bg-admin-form cols2" data-admin-modal-form="edit-user" data-id="${uid}">${field('نام','first_name',u.first_name||'')}${field('نام خانوادگی','last_name',u.last_name||'')}${field('ایمیل','email',u.email||'','email')}${field('شماره تماس','phone',u.phone_number||u.phone||'')}${field('نام کاربری وب','web_username',u.web_username||u.username||'')}${field('موجودی','balance',u.balance||0,'number')}<button class="full" type="submit">ذخیره کاربر</button></form>`) }
function settingsPayload(){const f=document.getElementById('bgAdminSettingsForm');if(!f)return{};const o=formDataObj(f);const has=k=>f.elements[k]?.checked;o.payment_methods_enabled={wallet:has('pm_wallet'),card:has('pm_card'),crypto:has('pm_crypto'),stars:has('pm_stars')};['require_email_verification','require_contact_auth','notify_new_user','storefront_announcement_enabled','crypto_notify_rate_fail','button_colors_enabled'].forEach(k=>{if(f.elements[k])o[k]=has(k)?1:0});if(settingsTab==='appearance')o.button_colors={primary:o.button_primary,secondary:o.button_secondary,danger:o.button_danger,success:o.button_success,warning:o.button_warning};delete o.vip_json;return o}
async function backupUpload(){const file=$q('#bgBackupUpload')?.files?.[0];if(!file)return toast('فایل بکاپ را انتخاب کن.','error');if(!confirm('کل دیتابیس با این بکاپ جایگزین شود؟'))return;const fd=new FormData();fd.append('confirm','RESTORE');fd.append('backup',file);const headers={};const t=window.BGApi?.token?.();if(t)headers['X-Web-Token']=t;root.classList.add('admin-busy');try{const r=await fetch(new URL('../backup_upload.php',location.href),{method:'POST',body:fd,headers,credentials:'same-origin'});const d=await r.json();if(!r.ok||d.ok===false)throw new Error(d.message||'Restore failed');toast(d.message||'Restore انجام شد.','success');location.reload()}catch(e){toast(e.message,'error')}finally{root.classList.remove('admin-busy')}}
async function broadcastModal(){modal('پیام همگانی',`<form class="bg-admin-form" data-admin-modal-form="broadcast"><label>متن پیام<textarea name="text" placeholder="HTML پشتیبانی می‌شود"></textarea></label><label>فایل ضمیمه اختیاری<input name="media" type="file" accept="image/*,video/*,audio/*,.pdf,.zip,.doc,.docx"></label><button type="submit">ارسال برای کاربران تلگرام</button></form>`)}
function rewardModal(){modal('ثبت پاداش خرید',`<form class="bg-admin-form" data-admin-modal-form="reward">${field('Telegram ID خریدار','buyer_tid','','number')}${field('مبلغ پایه خرید','base_amount','','number')}<button type="submit">ثبت پاداش</button></form>`)}
async function handleAction(b){const a=b.dataset.bgadminAction,id=Number(b.dataset.id||0);if(a==='reload')return reload();if(a==='order-view'){orderView=b.dataset.view;return renderPane()}if(a==='export-orders'){const rows=[['#','کاربر','محصول','مبلغ','پرداخت','وضعیت','تاریخ'],...(S.orders||[]).map(o=>[o.id,o.username||o.telegram_id,o.display_name,o.final_amount,o.payment_method_fa||o.payment_method,o.status_fa||o.status,o.created_at])];return downloadCsv('bluegate-orders.csv',rows)}if(a==='export-products'){const rows=[['#','نام','دسته','قیمت','واحد','فعال','ویژه','موجودی'],...(S.products||[]).map(p=>[p.id,p.name,p.category_title,p.price,p.price_currency,p.is_active,p.is_featured,p.inventory_available])];return downloadCsv('bluegate-products.csv',rows)}
if(a==='clear-selection'){selectedOrders.clear();return renderPane()}if(a==='bulk-status'){for(const oid of selectedOrders)await C.api('admin_order_status',{order_id:oid,status:b.dataset.status});selectedOrders.clear();return reload(false)}if(a==='cleanup'){if(!confirm('سفارش‌های قابل پاکسازی حذف کامل شوند؟'))return;return call('admin_cleanup_orders',{older_days:b.dataset.days},'پاکسازی انجام شد.')}if(a==='archive-order')return call('admin_archive_order',{order_id:id},'سفارش آرشیو شد.');if(a==='delete-order'){if(confirm('این سفارش برای همیشه حذف شود؟'))return call('admin_delete_order',{order_id:id},'سفارش حذف شد.')}if(a==='customer')return customerModal(Number(b.dataset.user));if(a==='order-open'){const o=(S.orders||[]).find(x=>Number(x.id)===id);if(o)modal(`سفارش #${id}`,orderCard(o),{wide:true});return}if(a==='receipt'){const r=await C.api('get_receipt_url',{order_id:id});if(r.url)modal(`رسید سفارش #${id}`,`<img class="bg-receipt-img" src="${esc(r.url)}" alt="receipt">`);return}if(a==='order-note'){const note=prompt('یادداشت داخلی سفارش:',b.dataset.note||'');if(note!==null)return call('admin_order_note',{order_id:id,note},'یادداشت ذخیره شد.')}if(a==='service'){const url=prompt('لینک HTTPS سرویس:',b.dataset.url||'https://');if(url===null)return;const title=prompt('عنوان دکمه:',b.dataset.title||'مدیریت سرویس');if(title===null)return;const note=prompt('پیام تحویل:','سرویس شما آماده است.');if(note===null)return;return call('admin_set_service_delivery',{order_id:id,delivery_url:url,delivery_title:title,delivery_note:note},'لینک سرویس ثبت شد.')}if(a==='deliver'){const delivery=prompt('متن تحویل:');if(delivery)return call('admin_deliver_order',{order_id:id,delivery},'سفارش تحویل شد.')}
if(a==='add-product')return modal('محصول جدید',productForm(),{wide:true});if(a==='edit-product'){const p=(S.products||[]).find(x=>Number(x.id)===id);return modal(`ویرایش ${esc(p?.name||'محصول')}`,productForm(p||{}),{wide:true})}if(a==='toggle-product')return call('admin_toggle_product',{product_id:id});if(a==='soft-delete-product'){if(confirm('محصول غیرفعال شود؟'))return call('admin_delete_product',{product_id:id})}if(a==='hard-delete-product'){if(confirm('حذف کامل محصول؟ در صورت داشتن سفارش ممکن نیست.'))return call('admin_hard_delete_product',{product_id:id})}if(a==='reorder-product'){const ids=(S.products||[]).map(x=>Number(x.id)),i=ids.indexOf(id),j=b.dataset.dir==='up'?i-1:i+1;if(i>=0&&j>=0&&j<ids.length){[ids[i],ids[j]]=[ids[j],ids[i]];return call('admin_reorder_products',{ordered_ids:ids},'ترتیب محصولات ذخیره شد.')}}
if(a==='add-category')return modal('دسته جدید',categoryForm());if(a==='edit-category'){const c=(S.categories||[]).find(x=>Number(x.id)===id);return modal('ویرایش دسته',categoryForm(c||{}))}if(a==='soft-delete-category'){if(confirm('دسته غیرفعال شود؟'))return call('admin_delete_category',{category_id:id})}if(a==='hard-delete-category'){if(confirm('دسته کامل حذف شود؟'))return call('admin_hard_delete_category',{category_id:id})}if(a==='reorder-category'){const ids=(S.categories||[]).map(x=>Number(x.id)),i=ids.indexOf(id),j=b.dataset.dir==='up'?i-1:i+1;if(i>=0&&j>=0&&j<ids.length){[ids[i],ids[j]]=[ids[j],ids[i]];return call('admin_reorder_categories',{ordered_ids:ids},'ترتیب دسته‌ها ذخیره شد.')}}
if(a==='add-variant')return modal('پلن جدید',variantForm({},id||''));if(a==='edit-variant'){const v=(S.variants||[]).find(x=>Number(x.id)===id);return modal('ویرایش پلن',variantForm(v||{}),{wide:true})}if(a==='soft-delete-variant'){if(confirm('پلن غیرفعال شود؟'))return call('admin_delete_variant',{variant_id:id})}if(a==='hard-delete-variant'){if(confirm('پلن کامل حذف شود؟'))return call('admin_hard_delete_variant',{variant_id:id})}
if(a==='add-inventory')return modal('افزودن انبار',inventoryForm(),{wide:true});if(a==='edit-inventory'){const i=(S.inventory||[]).find(x=>Number(x.id)===id);return modal('ویرایش انبار',inventoryForm(i||{}),{wide:true})}if(a==='soft-delete-inventory'){if(confirm('آیتم موجود حذف امن شود؟'))return call('admin_delete_inventory',{inventory_id:id})}if(a==='hard-delete-inventory'){if(confirm('آیتم کامل حذف شود؟'))return call('admin_hard_delete_inventory',{inventory_id:id})}
if(a==='add-coupon')return modal('کد تخفیف جدید',couponForm(),{wide:true});if(a==='edit-coupon'){const c=(S.coupons||[]).find(x=>Number(x.id)===id);return modal('ویرایش کد تخفیف',couponForm(c||{}),{wide:true})}if(a==='toggle-coupon')return call('admin_toggle_coupon',{coupon_id:id});if(a==='delete-coupon'){if(confirm('کد تخفیف حذف شود؟'))return call('admin_delete_coupon',{coupon_id:id})}
if(a==='withdraw')return call('admin_withdraw_action',{withdrawal_id:id,action_type:b.dataset.status},'وضعیت برداشت تغییر کرد.');if(a==='add-role')return modal('ادمین جدید',roleForm());if(a==='edit-role')return modal('ویرایش نقش',roleForm({telegram_id:b.dataset.tid,role:b.dataset.role,display_name:b.dataset.name}));if(a==='remove-role'){if(confirm('این نقش حذف شود؟'))return call('admin_remove_role',{telegram_id:Number(b.dataset.tid)},'نقش حذف شد.')}if(a==='ban-user'){if(confirm('این کاربر مسدود شود؟'))return call('admin_ban_user',{telegram_id:Number(b.dataset.tid)},'کاربر مسدود شد.')}if(a==='edit-user')return editUserModal(id);
if(a==='refresh-rates')return call('admin_refresh_crypto_rates',{},'نرخ‌ها تازه شدند.');if(a==='save-settings'){const o=settingsPayload();return call('admin_save_settings',o,'تنظیمات ذخیره شد.')}if(a==='save-vip'){const raw=$q('[name="vip_json"]')?.value||'[]';let arr;try{arr=JSON.parse(raw)}catch(_){return toast('JSON نرخ VIP معتبر نیست.','error')}return call('admin_save_vip_rates',{vip_tier_rates:arr},'نرخ‌های VIP ذخیره شد.')}
if(a==='broadcast')return broadcastModal();if(a==='reward')return rewardModal();if(a==='backup-create')return call('admin_backup_create',{},'Backup ساخته شد.');if(a==='backup-send')return call('admin_backup_send_bot',{},'Backup در Bot ارسال شد.');if(a==='backup-delete'){if(confirm('Backup حذف شود؟'))return call('admin_backup_delete',{filename:b.dataset.name},'Backup حذف شد.')}if(a==='backup-restore'){if(confirm('دیتابیس فعلی با این Backup جایگزین شود؟')){await call('admin_backup_restore_server',{filename:b.dataset.name,confirm:'RESTORE'},'Restore انجام شد.');location.reload()}return}if(a==='backup-upload')return backupUpload();}
async function handleSubmit(f){const kind=f.dataset.adminModalForm||f.dataset.adminForm;if(!kind)return;const o=formDataObj(f);if(kind==='order-search'){const r=await C.api('admin_search_orders',o);const box=document.getElementById('bgOrderResults');if(box)box.innerHTML=(r.orders||[]).map(orderCard).join('')||'<div class="bg-empty">نتیجه‌ای نیست.</div>';return}if(kind==='balance')return call('admin_add_balance',o,'موجودی تغییر کرد.');if(kind==='customer-lookup')return customerModal(Number(o.user_id));if(kind==='add-product'){o.is_featured=f.elements.is_featured?.checked?1:0;await call('admin_add_product',o,'محصول ساخته شد.');return closeModal()}if(kind==='edit-product'){o.product_id=Number(f.dataset.id);o.is_featured=f.elements.is_featured?.checked?1:0;o.is_active=f.elements.is_active?.checked?1:0;await call('admin_update_product',o,'محصول بروزرسانی شد.');return closeModal()}if(kind==='add-category'){await call('admin_add_category',o,'دسته ساخته شد.');return closeModal()}if(kind==='edit-category'){o.category_id=Number(f.dataset.id);o.is_active=f.elements.is_active?.checked?1:0;await call('admin_update_category',o,'دسته بروزرسانی شد.');return closeModal()}if(kind==='add-variant'){o.product_id=Number(o.product_id);await call('admin_add_variant',o,'پلن ساخته شد.');return closeModal()}if(kind==='edit-variant'){o.variant_id=Number(f.dataset.id);o.is_active=f.elements.is_active?.checked?1:0;delete o.product_id;await call('admin_update_variant',o,'پلن بروزرسانی شد.');return closeModal()}if(kind==='add-inventory'){await call('admin_add_inventory',o,'انبار اضافه شد.');return closeModal()}if(kind==='edit-inventory'){o.inventory_id=Number(f.dataset.id);await call('admin_update_inventory',o,'انبار بروزرسانی شد.');return closeModal()}if(kind==='add-coupon'){o.type=o.discount_type;o.value=o.discount_value;await call('admin_add_coupon',o,'کد تخفیف ساخته شد.');return closeModal()}if(kind==='edit-coupon'){o.coupon_id=Number(f.dataset.id);o.type=o.discount_type;o.value=o.discount_value;o.is_active=f.elements.is_active?.checked?1:0;await call('admin_update_coupon',o,'کد تخفیف بروزرسانی شد.');return closeModal()}if(kind==='role'){await call('admin_set_role',{telegram_id:Number(o.telegram_id),display_name:o.display_name,role:o.role},'نقش ذخیره شد.');return closeModal()}if(kind==='edit-user'){o.user_id=Number(f.dataset.id);await call('admin_edit_user',o,'کاربر بروزرسانی شد.');return closeModal()}if(kind==='reward'){await call('admin_purchase_reward',{buyer_tid:Number(o.buyer_tid),base_amount:Number(o.base_amount)},'پاداش ثبت شد.');return closeModal()}if(kind==='broadcast'){let media_b64=null,filename=null;const file=f.elements.media?.files?.[0];if(file){if(file.size>40*1024*1024)return toast('فایل بزرگ‌تر از ۴۰MB است.','error');filename=file.name;media_b64=await new Promise((res,rej)=>{const rd=new FileReader();rd.onload=()=>res(rd.result);rd.onerror=()=>rej(new Error('خواندن فایل ناموفق'));rd.readAsDataURL(file)})}await call('admin_broadcast',{text:o.text||'',media_b64,filename},'پیام همگانی ارسال شد.');return closeModal()}}
function bind(){if(bound||!root)return;bound=true;root.addEventListener('click',async e=>{const t=e.target.closest('[data-bgadmin-tab],[data-bgadmin-action],[data-settings-tab]');if(!t)return;e.preventDefault();if(t.dataset.bgadminTab){tab=t.dataset.bgadminTab;renderPane();$$('[data-bgadmin-tab]',root).forEach(b=>b.classList.toggle('active',b.dataset.bgadminTab===tab));return}if(t.dataset.settingsTab){settingsTab=t.dataset.settingsTab;$$('[data-settings-tab]',root).forEach(x=>x.classList.toggle('active',x.dataset.settingsTab===settingsTab));$$('[data-settings-pane]',root).forEach(x=>x.classList.toggle('hidden',x.dataset.settingsPane!==settingsTab));return}try{await handleAction(t)}catch(_){}});root.addEventListener('change',async e=>{if(e.target.matches('[data-order-select]')){const id=Number(e.target.dataset.orderSelect);e.target.checked?selectedOrders.add(id):selectedOrders.delete(id);renderPane()}if(e.target.matches('[data-order-status]')&&e.target.value){try{await call('admin_order_status',{order_id:Number(e.target.dataset.orderStatus),status:e.target.value},'وضعیت سفارش تغییر کرد.')}catch(_){}}});root.addEventListener('submit',async e=>{const f=e.target.closest('form');if(!f)return;e.preventDefault();try{await handleSubmit(f)}catch(_){}});document.addEventListener('click',async e=>{if(e.target.closest('[data-admin-modal-close]')){closeModal();return}const a=e.target.closest('#bgAdminModal [data-bgadmin-action]');if(a){e.preventDefault();try{await handleAction(a)}catch(_){}}});document.addEventListener('change',async e=>{const st=e.target.closest('#bgAdminModal [data-order-status]');if(st&&st.value){try{await call('admin_order_status',{order_id:Number(st.dataset.orderStatus),status:st.value},'وضعیت سفارش تغییر کرد.');closeModal()}catch(_){}}});document.addEventListener('submit',async e=>{const f=e.target.closest('#bgAdminModal form');if(!f)return;e.preventDefault();try{await handleSubmit(f)}catch(_){}})}
window.BGWebAdmin={mount(opts){C=opts;S=opts.state;root=opts.container;tab=opts.tab||tab;shell()},refresh:reload};
})();
